    char full_path[PATH_MAX];
    snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, filename);

    char normalized_path[PATH_MAX];
    if (realpath(full_path, normalized_path) == NULL) {
        return strdup("");
    }

    if (strncmp(normalized_path, dir_path, strlen(dir_path)) != 0 || 
        normalized_path[strlen(dir_path)] != '/') {
        return strdup("");
    }

    int fd = open(normalized_path, O_RDONLY);
    if (fd == -1) {
        return strdup("");
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        close(fd);
        return strdup("");
    }

    char *content = (char *)malloc(st.st_size + 1);
    if (!content) {
        close(fd);
        return strdup("");
    }

    ssize_t bytes_read = read(fd, content, st.st_size);
    if (bytes_read == -1 || (size_t)bytes_read != st.st_size) {
        free(content);
        close(fd);
        return strdup("");
    }

    content[st.st_size] = '\0';
    close(fd);
    return content;
}
